#include "../include/dtop_solution_renderer.h"
#include <iostream>
#include <cstdlib>
#include <iomanip>

/**
 * @brief Prints a summary of the DTOP solution to the standard output.
 * 
 * @param solution The solution generated by the algorithm.
 * @param instance The original problem instance.
 */
void SolutionRenderer::PrintConsoleSummary(const DTOPSolution& solution, const DTOPInstance& instance) {
  std::cout << "=== DTOP Solution ===\n";
  std::cout << "Total Profit: " << solution.GetTotalProfit() << "\n";
  
  for (size_t i = 0; i < solution.GetFirstNodes().size(); ++i) {
    PrintSingleRoute(solution, i, instance.GetNumberOfNodes() - 1);
  }
}

/**
 * @brief Exports the solution to a Graphviz-compatible format.
 * 
 * @param solution The solution containing the vehicle routes.
 * @param instance The original instance used to extract spatial coordinates and rewards.
 * @param filename Name and path of the temporary .dot file to generate.
 */
void SolutionRenderer::ExportToGraphviz(const DTOPSolution& solution, const DTOPInstance& instance, const std::string& filename) {
  std::ofstream out(filename);
  if (!out.is_open()) {
    std::cerr << "Error al crear el archivo DOT: " << filename << "\n";
    return;
  }
  int end_depot_id = instance.GetNumberOfNodes() - 1;

  WriteGraphvizHeader(out);
  WriteGraphvizNodes(out, solution, instance, end_depot_id);
  WriteGraphvizRoutes(out, solution, instance);
  out << "}\n";
  out.close();
  CompileGraphviz(filename);
}

/**
 * @brief Displays the sequence of nodes visited by a vehicle, its duration, and profit on the console.
 * 
 * @param solution The solution containing the linked lists of the routes.
 * @param route_index Index of the vehicle/route to print.
 * @param end_depot_id Numeric identifier of the closing end depot.
 */
void SolutionRenderer::PrintSingleRoute(const DTOPSolution& solution, size_t route_index, int end_depot_id) {
  const auto& first_nodes = solution.GetFirstNodes();
  const auto& next_nodes = solution.GetNextNodes();
  const auto& profits = solution.GetRouteProfits();
  const auto& durations = solution.GetRouteDurations();

  std::cout << "Route " << route_index << ": 0"; 
  
  int current = first_nodes[route_index];
  while (current != -1 && current != end_depot_id) {
    std::cout << " -> " << current;
    current = next_nodes[current];
  }
  
  std::cout << " -> " << end_depot_id;
      
  if (route_index < profits.size() && route_index < durations.size()) {
    std::cout << " | Profit: " << profits[route_index] 
              << " | Duration: " << durations[route_index];
  }
  std::cout << "\n";
}

/**
 * @brief Writes the initial graph declaration and base styling configuration to the DOT file.
 * 
 * @param out Output stream associated with the DOT text file.
 */
void SolutionRenderer::WriteGraphvizHeader(std::ofstream& out) {
  out << "digraph DTOP {\n";
  out << "  node [shape=circle, style=filled, fontcolor=black, fontsize=20, width=0.8, height=0.8];\n";
}

/**
 * @brief Draws the graph nodes respecting their physical coordinates and applying conditional styling (colors and labels).
 * 
 * @param out Output stream associated with the DOT file.
 * @param solution Solution used to verify the visited state of each node.
 * @param instance Instance used to extract the real coordinates and rewards.
 * @param end_depot_id Numeric identifier of the end depot.
 */
void SolutionRenderer::WriteGraphvizNodes(std::ofstream& out, const DTOPSolution& solution, const DTOPInstance& instance, int end_depot_id) {
  const auto& clients = instance.GetClients();
  const auto& visited = solution.GetVisited();

  for (int i = 0; i <= end_depot_id; ++i) {
    out << "  " << i << " [pos=\"" << (clients[i].x_coordinate * kNodeScale) << "," 
                                   << (clients[i].y_coordinate * kNodeScale) << "!\"";
    
    if (i == 0 || i == end_depot_id) {
      out << ", fillcolor=black, fontcolor=white, shape=doublecircle";
    } else {
      out << ", xlabel=<<font color=\"darkgreen\" point-size=\"18\"><b>+" << clients[i].reward << "</b></font>>";
      if (visited[i]) {
        out << ", fillcolor=lightgreen";
      } else {
        out << ", fillcolor=white";
      }
    }
    out << "];\n";
  }
}

/**
 * @brief Generates the edges (connections) representing the constructed routes, assigning a distinctive color to each vehicle.
 * 
 * @param out Output stream associated with the DOT file.
 * @param solution Solution containing the start and continuation vectors for each route.
 * @param end_depot_id Numeric identifier of the end depot.
 */
void SolutionRenderer::WriteGraphvizRoutes(std::ofstream& out, const DTOPSolution& solution, const DTOPInstance& instance) {
  const auto& first_nodes = solution.GetFirstNodes();
  const auto& next_nodes = solution.GetNextNodes();
  const auto& distances = instance.GetDistances();
  int end_depot_id = instance.GetNumberOfNodes() - 1;

  out << std::fixed << std::setprecision(2);

  for (size_t i = 0; i < first_nodes.size(); ++i) {
    std::string color = kRouteColors[i % kRouteColors.size()];
    int current = first_nodes[i];
    
    if (current == -1 || current == end_depot_id) {
      double dist = distances[0][end_depot_id];
      out << "  0 -> " << end_depot_id << " [color=\"" << color << "\", style=dashed"
          << ", label=\"" << dist << "\", fontcolor=\"" << color << "\", fontsize=20];\n";
      continue;
    }

    double dist_start = distances[0][current];
    out << "  0 -> " << current << " [color=\"" << color << "\", penwidth=2.0"
        << ", label=\"" << dist_start << "\", fontcolor=\"" << color << "\", fontsize=20];\n";    
    
    while (next_nodes[current] != -1 && next_nodes[current] != end_depot_id) {
      int next = next_nodes[current];
      double dist_mid = distances[current][next];
      out << "  " << current << " -> " << next << " [color=\"" << color << "\", penwidth=2.0"
          << ", label=\"" << dist_mid << "\", fontcolor=\"" << color << "\", fontsize=20];\n";
      current = next;
    }
    
    double dist_end = distances[current][end_depot_id];
    out << "  " << current << " -> " << end_depot_id << " [color=\"" << color << "\", penwidth=2.0"
        << ", label=\"" << dist_end << "\", fontcolor=\"" << color << "\", fontsize=20];\n";
  }
}

/**
 * @brief Invokes the Graphviz neato engine via a system call to generate a rendered PDF of the graph.
 * 
 * @param filename Name of the source DOT file to compile.
 */
void SolutionRenderer::CompileGraphviz(const std::string& filename) {
  std::string pdf_filename = "../outputs/solucion_dtop.pdf";
  std::string command = "neato -Tpdf " + filename + " -o " + pdf_filename;
  
  if (std::system(command.c_str()) == 0) {
    std::cout << "Grafo generado exitosamente en " << pdf_filename << "\n";
  } else {
    std::cout << "El archivo .dot se generó, pero falló la compilación a PDF.\n";
  }
}